//! The enums of the C API as Rust enums, generated by `libbitwuzla-sys` from the
//! C headers (see `build.rs`).
//!
//! Each enum has an `ALL` array and converts to (`From`) and from (`TryFrom`)
//! the integer type of its C counterpart in [`crate::sys`].

// The docs are the C API's Doxygen comments (e.g., "<stdout>").
#![allow(rustdoc::invalid_html_tags)]
#![allow(clippy::all)]

include!(env!("BITWUZLA_RUST_ENUMS"));
